#!/usr/bin/env node
// Extracts every matchup tip shown on the site into tools/i18n-matchups/source.json.
// Source: public/assets/data/matchups/<slug>.json (generated by tools/split-guides.mjs from data/lol).
//
// One entry per (champion, enemy) pair. Id: `champion|enemy|index`, slugs; `index` is the position of the
// tip block inside the matchup (always 0 today: one block per matchup). Only `text` gets translated;
// `champion`, `enemy` and `level` must stay identical in the translation (checked by check.mjs).
//
// Usage: node tools/i18n-matchups/extract-source.mjs

import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const ROOT = fileURLToPath(new URL('../..', import.meta.url));
const MATCHUPS_DIR = join(ROOT, 'public/assets/data/matchups');
const OUT = fileURLToPath(new URL('./source.json', import.meta.url));

export const slugify = (s) =>
  s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const entries = [];
for (const file of readdirSync(MATCHUPS_DIR).sort()) {
  const data = JSON.parse(readFileSync(join(MATCHUPS_DIR, file), 'utf8'));
  for (const m of data.matchups) {
    const text = (m.tips ?? '').trim();
    if (!text) continue;
    entries.push({
      id: `${slugify(data.champion)}|${slugify(m.enemy)}|0`,
      champion: data.champion,
      enemy: m.enemy,
      level: m.level,
      text,
    });
  }
}

const ids = new Set(entries.map((e) => e.id));
if (ids.size !== entries.length) throw new Error('Duplicate ids in source');

writeFileSync(OUT, JSON.stringify(entries, null, 1) + '\n');
const champions = new Set(entries.map((e) => e.champion)).size;
const chars = entries.reduce((n, e) => n + e.text.length, 0);
console.log(`${champions} champions · ${entries.length} tips · ${chars} characters → ${OUT}`);
